            "is_getter_or_setter": false,
            "code": "```java\nprivate int readWithQuotes(final char[] srcChars, final int start, final int len, final StrBuilder workArea, final List<String> tokenList, final int quoteStart, final int quoteLen)  {\n    // Loop until we've found the end of the quoted // string or the end of the input workArea.clear();\n    int pos = start;\n    boolean quoting = quoteLen > 0;\n    int trimStart = 0;\n    while (pos < len)\n    {\n        // quoting mode can occur several times throughout a string // we must switch between quoting and non-quoting until we // encounter a non-quoted delimiter, or end of string if (quoting)\n        {\n            // In quoting mode // If we've found a quote character, see if it's // followed by a second quote. If so, then we need // to actually put the quote character into the token // rather than end the token. if (isQuote(srcChars, pos, len, quoteStart, quoteLen))\n            {\n                if (isQuote(srcChars, pos + quoteLen, len, quoteStart, quoteLen))\n                {\n                    // matched pair of quotes, thus an escaped quote workArea.append(srcChars, pos, quoteLen);\n                    pos += quoteLen * 2;\n                    trimStart = workArea.size();\n                    continue;\n                }\n                // end of quoting quoting = false;\n                pos += quoteLen;\n                continue;\n            }\n        }\n        else\n        {\n            // Not in quoting mode // check for delimiter, and thus end of token final int delimLen = getDelimiterMatcher().isMatch(srcChars, pos, start, len);\n            if (delimLen > 0)\n            {\n                // return condition when end of token found addToken(tokenList, workArea.substring(0, trimStart));\n                return pos + delimLen;\n            }\n            // check for quote, and thus back into quoting mode if (quoteLen > 0 && isQuote(srcChars, pos, len, quoteStart, quoteLen))\n            {\n                quoting = true;\n                pos += quoteLen;\n                continue;\n            }\n            // check for ignored (outside quotes), and ignore final int ignoredLen = getIgnoredMatcher().isMatch(srcChars, pos, start, len);\n            if (ignoredLen > 0)\n            {\n                pos += ignoredLen;\n                continue;\n            }\n            // check for trimmed character // don't yet know if it's at the end, so copy to workArea // use trimStart to keep track of trim at the end final int trimmedLen = getTrimmerMatcher().isMatch(srcChars, pos, start, len);\n            if (trimmedLen > 0)\n            {\n                workArea.append(srcChars, pos, trimmedLen);\n                pos += trimmedLen;\n                continue;\n            }\n        }\n        // copy regular character from inside quotes workArea.append(srcChars[pos++]);\n        trimStart = workArea.size();\n    }\n    // return condition when end of string found addToken(tokenList, workArea.substring(0, trimStart));\n    return -1;\n}\n```"
