void testClientWaitStats() throws TestException  {
    final SimpleFactory<String> factory = new SimpleFactory<>();
    // Give makeObject a little latency factory.setMakeLatency(200);
    try (GenericKeyedObjectPool<String, String, TestException> pool = new GenericKeyedObjectPool<>(factory, new GenericKeyedObjectPoolConfig<>()))
    {
        final String s = pool.borrowObject("one");
        // First borrow waits on create, so wait time should be at least 200 ms // Allow 100ms error in clock times assertTrue(pool.getMaxBorrowWaitTimeMillis() >= 100);
        assertTrue(pool.getMeanBorrowWaitTimeMillis() >= 100);
        pool.returnObject("one", s);
        pool.borrowObject("one");
        // Second borrow does not have to wait on create, average should be about 100 assertTrue(pool.getMaxBorrowWaitTimeMillis() > 100);
        assertTrue(pool.getMeanBorrowWaitTimeMillis() < 200);
        assertTrue(pool.getMeanBorrowWaitTimeMillis() > 20);
    }
}
