                        final ObjectDeque<T> objectDeque = poolMap.get(evictionKey);
                        if (objectDeque == null)
                        {
                            continue;
                        }
                        final Deque<PooledObject<T>> idleObjects = objectDeque.getIdleObjects();
                        evictionIterator = new EvictionIterator(idleObjects);
                        if (evictionIterator.hasNext())
