                        final NoSuchElementException nsee = new NoSuchElementException(appendStats("Unable to validate object"));
                        nsee.initCause(validationThrowable);
                        throw nsee;
                    }
                }
            }
        }
    }
    updateStatsBorrow(p, durationSince(startInstant));
    return p.getObject();
}
