void testConcurrentInvalidate() throws Exception  {
    // Get allObjects and idleObjects loaded with some instances final int nObjects = 1000;
    genericObjectPool.setMaxTotal(nObjects);
    genericObjectPool.setMaxIdle(nObjects);
    final String[] obj = new String[nObjects];
    for (int i = 0;
    i < nObjects;
    i++)
    {
        obj[i] = genericObjectPool.borrowObject();
    }
    for (int i = 0;
    i < nObjects;
    i++)
    {
        if (i % 2 == 0)
        {
            genericObjectPool.returnObject(obj[i]);
        }
    }
    final int nThreads = 20;
    final int nIterations = 60;
    final InvalidateThread[] threads = new InvalidateThread[nThreads];
    // Randomly generated list of distinct invalidation targets final ArrayList<Integer> targets = new ArrayList<>();
    final Random random = new Random();
    for (int j = 0;
    j < nIterations;
    j++)
    {
        // Get a random invalidation target Integer targ = Integer.valueOf(random.nextInt(nObjects));
        while (targets.contains(targ))
        {
            targ = Integer.valueOf(random.nextInt(nObjects));
        }
        targets.add(targ);
        // Launch nThreads threads all trying to invalidate the target for (int i = 0;
        i < nThreads;
        i++)
        {
            threads[i] = new InvalidateThread(genericObjectPool, obj[targ.intValue()]);
        }
        for (int i = 0;
        i < nThreads;
        i++)
        {
            new Thread(threads[i]).start();
        }
        boolean done = false;
        while (!done)
        {
            done = true;
            for (int i = 0;
            i < nThreads;
            i++)
            {
                done = done && threads[i].complete();
            }
            Thread.sleep(100);
        }
    }
    assertEquals(nIterations, genericObjectPool.getDestroyedCount());
}
