void testFailingFactoryDoesNotBlockThreads() throws Exception  {
    final CreateFailFactory factory = new CreateFailFactory();
    try (GenericObjectPool<String, InterruptedException> createFailFactoryPool = new GenericObjectPool<>( factory))
    {
        createFailFactoryPool.setMaxTotal(1);
        // Try and borrow the first object from the pool final WaitingTestThread<InterruptedException> thread1 = new WaitingTestThread<>(createFailFactoryPool, 0);
        thread1.start();
        // Wait for thread to reach semaphore while (!factory.hasQueuedThreads())
        {
            Thread.sleep(200);
        }
        // Try and borrow the second object from the pool final WaitingTestThread<InterruptedException> thread2 = new WaitingTestThread<>(createFailFactoryPool, 0);
        thread2.start();
        // Pool will not call factory since maximum number of object creations // are already queued. // Thread 2 will wait on an object being returned to the pool // Give thread 2 a chance to reach this state Thread.sleep(1000);
        // Release thread1 factory.release();
        // Pre-release thread2 factory.release();
        // Both threads should now complete. boolean threadRunning = true;
        int count = 0;
        while (threadRunning && count < 15)
        {
            threadRunning = thread1.isAlive();
            threadRunning = thread2.isAlive();
            Thread.sleep(200);
            count++;
        }
        assertFalse(thread1.isAlive());
        assertFalse(thread2.isAlive());
        assertTrue(thread1.thrown instanceof UnsupportedCharsetException, () -> Objects.toString(thread1.thrown));
        assertTrue(thread2.thrown instanceof UnsupportedCharsetException, () -> Objects.toString(thread2.thrown));
    }
}
