    {
        @Override public String create()
        {
            return null;
        }
        @Override public PooledObject<String> wrap(final String obj)
        {
            return new DefaultPooledObject<>(obj);
        }
    }
    ))
    {
        // Start evictor #1 final BaseGenericObjectPool<String, RuntimeException>.Evictor evictor1 = pool.new Evictor();
        EvictionTimer.schedule(evictor1, TestConstants.ONE_MINUTE_DURATION, TestConstants.ONE_MINUTE_DURATION);
        // Assert that eviction objects are correctly allocated // 1 - the evictor timer task is created final Field evictorTaskFutureField = evictor1.getClass().getDeclaredField("scheduledFuture");
        evictorTaskFutureField.setAccessible(true);
        ScheduledFuture<?> sf = (ScheduledFuture<?>) evictorTaskFutureField.get(evictor1);
        assertFalse(sf.isCancelled());
        // 2- and, the eviction action is added to executor thread pool final Field evictorExecutorField = EvictionTimer.class.getDeclaredField("executor");
        evictorExecutorField.setAccessible(true);
        final ThreadPoolExecutor evictionExecutor = (ThreadPoolExecutor) evictorExecutorField.get(null);
        assertEquals(2, evictionExecutor.getQueue().size());
        // Reaper plus one eviction task assertEquals(1, EvictionTimer.getNumTasks());
        // Start evictor #2 final BaseGenericObjectPool<String, RuntimeException>.Evictor evictor2 = pool.new Evictor();
        EvictionTimer.schedule(evictor2, TestConstants.ONE_MINUTE_DURATION, TestConstants.ONE_MINUTE_DURATION);
        // Assert that eviction objects are correctly allocated // 1 - the evictor timer task is created sf = (ScheduledFuture<?>) evictorTaskFutureField.get(evictor2);
        assertFalse(sf.isCancelled());
        // 2- and, the eviction action is added to executor thread pool assertEquals(3, evictionExecutor.getQueue().size());
        // Reaper plus 2 eviction tasks assertEquals(2, EvictionTimer.getNumTasks());
        // Stop evictor #1 EvictionTimer.cancel(evictor1, BaseObjectPoolConfig.DEFAULT_EVICTOR_SHUTDOWN_TIMEOUT, false);
        // Assert that eviction objects are correctly cleaned // 1 - the evictor timer task is cancelled sf = (ScheduledFuture<?>) evictorTaskFutureField.get(evictor1);
        assertTrue(sf.isCancelled());
        // 2- and, the eviction action is removed from executor thread pool final ThreadPoolExecutor evictionExecutorOnStop = (ThreadPoolExecutor) evictorExecutorField.get(null);
        assertEquals(2, evictionExecutorOnStop.getQueue().size());
        assertEquals(1, EvictionTimer.getNumTasks());
        // Stop evictor #2 EvictionTimer.cancel(evictor2, BaseObjectPoolConfig.DEFAULT_EVICTOR_SHUTDOWN_TIMEOUT, false);
