         {\n                swallowException(e);\n            }\n        }\n        else\n        {\n            if (getLifo())\n            {\n                idleObjects.addFirst(p);\n            }\n            else\n            {\n                idleObjects.addLast(p);\n            }\n            if (isClosed())\n            {\n                // Pool closed while object was being added to idle objects. // Make sure the returned object is destroyed rather than left // in the idle object pool (which would effectively be a leak) clear(key);\n            }\n        }\n    }\n    finally\n    {\n        if (hasBorrowWaiters())\n        {\n            reuseCapacity();\n        }\n        updateStatsReturn(activeTime);\n    }\n}\n```"
