    // build sorted map of idle objects final TreeMap<PooledObject<T>, K> map = new TreeMap<>();
    // Each item into the map using the PooledObject object as the // key. It then gets sorted based on the idle time poolMap.forEach((key, value) -> value.getIdleObjects().forEach(p -> map.put(p, key)));
    // Now iterate created map and kill the first 15% plus one to account // for zero int itemsToRemove = (int) (map.size() * 0.15) + 1;
    final Iterator<Entry<PooledObject<T>, K>> iter = map.entrySet().iterator();
    while (iter.hasNext() && itemsToRemove > 0)
    {
        final Entry<PooledObject<T>, K> entry = iter.next();
