private int calculateDeficit(final ObjectDeque<T> objectDeque)  {
    if (objectDeque == null)
    {
        return getMinIdlePerKey();
    }
    // Used more than once so keep a local copy so the value is consistent final int maxTotal = getMaxTotal();
    final int maxTotalPerKeySave = getMaxTotalPerKey();
    // Calculate no of objects needed to be created, in order to have // the number of pooled objects < maxTotalPerKey();
    int objectDefecit = getMinIdlePerKey() - objectDeque.getIdleObjects().size();
    if (maxTotalPerKeySave > 0)
    {
        final int growLimit = Math.max(0, maxTotalPerKeySave - objectDeque.getIdleObjects().size());
        objectDefecit = Math.min(objectDefecit, growLimit);
    }
    // Take the maxTotal limit into account if (maxTotal > 0)
    {
        final int growLimit = Math.max(0, maxTotal - getNumActive() - getNumIdle());
        objectDefecit = Math.min(objectDefecit, growLimit);
    }
    return objectDefecit;
}
