void testMaxTotalUnderLoad()  {
    // Config final int numThreads = 199;
    // And main thread makes a round 200. final int numIter = 20;
    final int delay = 25;
    final int maxTotal = 10;
    simpleFactory.setMaxTotal(maxTotal);
    genericObjectPool.setMaxTotal(maxTotal);
    genericObjectPool.setBlockWhenExhausted(true);
    genericObjectPool.setDurationBetweenEvictionRuns(Duration.ofMillis(-1));
    // Start threads to borrow objects final TestThread[] threads = new TestThread[numThreads];
    for (int i = 0;
    i < numThreads;
    i++)
    {
        // Factor of 2 on iterations so main thread does work whilst other // threads are running. Factor of 2 on delay so average delay for // other threads == actual delay for main thread threads[i] = new TestThread<>(genericObjectPool, numIter * 2, delay * 2);
        final Thread t = new Thread(threads[i]);
        t.start();
    }
    // Give the threads a chance to start doing some work Waiter.sleepQuietly(5000);
    for (int i = 0;
    i < numIter;
    i++)
    {
        String obj = null;
        try
        {
            Waiter.sleepQuietly(delay);
            obj = genericObjectPool.borrowObject();
            // Under load, observed numActive > maxTotal if (genericObjectPool.getNumActive() > genericObjectPool.getMaxTotal())
            {
                throw new IllegalStateException("Too many active objects");
            }
            Waiter.sleepQuietly(delay);
        }
        catch (final Exception e)
        {
            // Shouldn't happen e.printStackTrace();
            fail("Exception on borrow");
        }
        finally
        {
            if (obj != null)
            {
                try
                {
                    genericObjectPool.returnObject(obj);
                }
                catch (final Exception e)
                {
                    // Ignore
                }
            }
        }
    }
    for (int i = 0;
    i < numThreads;
    i++)
    {
        while (!threads[i].complete())
        {
            Waiter.sleepQuietly(500L);
        }
        if (threads[i].failed())
        {
            fail("Thread " + i + " failed: " + threads[i].error.toString());
        }
    }
}
