void testErodingPoolKeyedObjectPool() throws InterruptedException  {
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null), "PoolUtils.erodingPool(KeyedObjectPool) must not allow a null pool.");
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null, 1f), "PoolUtils.erodingPool(KeyedObjectPool, float) must not allow a null pool.");
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null, 1f, true), "PoolUtils.erodingPool(KeyedObjectPool, float, boolean) must not allow a null pool.");
    final List<String> calledMethods = new ArrayList<>();
    final InvocationHandler handler = new MethodCallLogger(calledMethods)
    {
        @Override public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable
        {
            Object o = super.invoke(proxy, method, args);
            if (o instanceof Integer)
            {
                // so getNumActive/getNumIdle are not zero. o = Integer.valueOf(1);
            }
            return o;
        }
    }
    ;
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool(createProxy(KeyedObjectPool.class, handler), 0f), "PoolUtils.erodingPool(ObjectPool, float) must not allow a non-positive factor.");
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool(createProxy(KeyedObjectPool.class, handler), 0f, false), "PoolUtils.erodingPool(ObjectPool, float, boolean) must not allow a non-positive factor.");
    // If the logic behind PoolUtils.erodingPool changes then this will need to be tweaked. final float factor = 0.01f;
    // about ~9 seconds until first discard final List<String> expectedMethods = new ArrayList<>();
    try (@SuppressWarnings("unchecked") KeyedObjectPool<Object, Object, RuntimeException> pool = PoolUtils.erodingPool(createProxy(KeyedObjectPool.class, handler), factor))
    {
        assertEquals(expectedMethods, calledMethods);
        final Object key = "key";
        pool.addObject(key);
        expectedMethods.add("addObject");
        Object o = pool.borrowObject(key);
        expectedMethods.add("borrowObject");
        assertEquals(expectedMethods, calledMethods);
        pool.returnObject(key, o);
        expectedMethods.add("returnObject");
        assertEquals(expectedMethods, calledMethods);
        // the invocation handler always returns 1 assertEquals(1, pool.getNumActive());
        expectedMethods.add("getNumActive");
        assertEquals(1, pool.getNumIdle());
        expectedMethods.add("getNumIdle");
        for (int i = 0;
        i < 5;
        i++)
        {
            o = pool.borrowObject(key);
            expectedMethods.add("borrowObject");
            Thread.sleep(50);
            pool.returnObject(key, o);
            expectedMethods.add("returnObject");
            assertEquals(expectedMethods, calledMethods);
            expectedMethods.clear();
            calledMethods.clear();
        }
        Thread.sleep(10000);
        // 10 seconds o = pool.borrowObject(key);
        expectedMethods.add("borrowObject");
        pool.returnObject(key, o);
        expectedMethods.add("getNumIdle");
        expectedMethods.add("invalidateObject");
        pool.clear();
    }
    expectedMethods.add("clear");
    expectedMethods.add("close");
    assertEquals(expectedMethods, calledMethods);
}
