void testBorrowTimings() throws Exception  {
    // Borrow final String object = genericObjectPool.borrowObject();
    final PooledObject<String> po = genericObjectPool.getPooledObject(object);
    // In the initial state, all instants are the creation instant: last borrow, // last use, last return. // In the initial state, the active duration is the time between "now" and the // creation time. // In the initial state, the idle duration is the time between "now" and the // last return, which is the creation time. // But... this PO might have already been used in other tests in this class. final Instant lastBorrowInstant1 = po.getLastBorrowInstant();
    final Instant lastReturnInstant1 = po.getLastReturnInstant();
    final Instant lastUsedInstant1 = po.getLastUsedInstant();
    assertTrue(po.getCreateInstant().compareTo(lastBorrowInstant1) <= 0);
    assertTrue(po.getCreateInstant().compareTo(lastReturnInstant1) <= 0);
    assertTrue(po.getCreateInstant().compareTo(lastUsedInstant1) <= 0);
    // Sleep MUST be "long enough" to detect that more than 0 milliseconds have // elapsed. // Need an API in Java 8 to get the clock granularity. Thread.sleep(200);
    assertFalse(po.getActiveDuration().isNegative());
    assertFalse(po.getActiveDuration().isZero());
    // We use greaterThanOrEqualTo instead of equal because "now" many be different // when each argument is evaluated. assertTrue(Duration.ZERO.compareTo(Duration.ZERO.plusNanos(1)) <= 0);
    // sanity check assertTrue(po.getActiveDuration().compareTo(po.getIdleDuration()) <= 0);
    assertTrue(po.getActiveDuration().compareTo(po.getActiveDuration()) <= 0);
    // // TODO How to compare ID with AD since other tests may have touched the PO? assertTrue(po.getActiveDuration().compareTo(po.getIdleDuration()) <= 0);
    // assertTrue(po.getCreateInstant().compareTo(po.getLastBorrowInstant()) <= 0);
    assertTrue(po.getCreateInstant().compareTo(po.getLastReturnInstant()) <= 0);
    assertTrue(po.getCreateInstant().compareTo(po.getLastUsedInstant()) <= 0);
    assertTrue(lastBorrowInstant1.compareTo(po.getLastBorrowInstant()) <= 0);
    assertTrue(lastReturnInstant1.compareTo(po.getLastReturnInstant()) <= 0);
    assertTrue(lastUsedInstant1.compareTo(po.getLastUsedInstant()) <= 0);
    genericObjectPool.returnObject(object);
    assertFalse(po.getActiveDuration().isNegative());
    assertFalse(po.getActiveDuration().isZero());
    assertTrue(po.getActiveDuration().compareTo(po.getActiveDuration()) <= 0);
    assertTrue(lastBorrowInstant1.compareTo(po.getLastBorrowInstant()) <= 0);
    assertTrue(lastReturnInstant1.compareTo(po.getLastReturnInstant()) <= 0);
    assertTrue(lastUsedInstant1.compareTo(po.getLastUsedInstant()) <= 0);
}
