public final void translate(final CharSequence input, final Writer writer) throws IOException  {
    Validate.isTrue(writer != null, "The Writer must not be null");
    if (input == null)
    {
        return;
    }
    int pos = 0;
    final int len = input.length();
    while (pos < len)
    {
        final int consumed = translate(input, pos, writer);
        if (consumed == 0)
        {
            // inlined implementation of Character.toChars(Character.codePointAt(input, pos)) // avoids allocating temp char arrays and duplicate checks final char c1 = input.charAt(pos);
            writer.write(c1);
            pos++;
            if (Character.isHighSurrogate(c1) && pos < len)
            {
                final char c2 = input.charAt(pos);
                if (Character.isLowSurrogate(c2))
                {
                    writer.write(c2);
                    pos++;
                }
            }
            continue;
        }
        // contract with translators is that they have to understand code points // and they just took care of a surrogate pair for (int pt = 0;
        pt < consumed;
        pt++)
        {
            pos += Character.charCount(Character.codePointAt(input, pos));
        }
    }
}
