            "code": "```java\nprivate int substitute(final StrBuilder buf, final int offset, final int length, List<String> priorVariables)  {\n    final StrMatcher pfxMatcher = getVariablePrefixMatcher();\n    final StrMatcher suffMatcher = getVariableSuffixMatcher();\n    final char escape = getEscapeChar();\n    final StrMatcher valueDelimMatcher = getValueDelimiterMatcher();\n    final boolean substitutionInVariablesEnabled = isEnableSubstitutionInVariables();\n    final boolean substitutionInValuesDisabled = isDisableSubstitutionInValues();\n    final boolean top = priorVariables == null;\n    boolean altered = false;\n    int lengthChange = 0;\n    char[] chars = buf.buffer;\n    int bufEnd = offset + length;\n    int pos = offset;\n    while (pos < bufEnd)\n    {\n        final int startMatchLen = pfxMatcher.isMatch(chars, pos, offset, bufEnd);\n        if (startMatchLen == 0)\n        {\n            pos++;\n        }\n        else // found variable start marker if (pos > offset && chars[pos - 1] == escape)\n        {\n            // escaped if (preserveEscapes)\n            {\n                pos++;\n                continue;\n            }\n            buf.deleteCharAt(pos - 1);\n            chars = buf.buffer;\n            // in case buffer was altered lengthChange--;\n            altered = true;\n            bufEnd--;\n        }\n        else\n        {\n            // find suffix final int startPos = pos;\n            pos += startMatchLen;\n            int endMatchLen = 0;\n            int nestedVarCount = 0;\n            while (pos < bufEnd)\n            {\n                if (substitutionInVariablesEnabled && pfxMatcher.isMatch(chars, pos, offset, bufEnd) != 0)\n                {\n                    // found a nested variable start endMatchLen = pfxMatcher.isMatch(chars, pos, offset, bufEnd);\n                    nestedVarCount++;\n                    pos += endMatchLen;\n                    continue;\n                }\n                endMatchLen = suffMatcher.isMatch(chars, pos, offset, bufEnd);\n                if (endMatchLen == 0)\n                {\n                    pos++;\n                }\n                else\n                {\n                    // found variable end marker if (nestedVarCount == 0)\n                    {\n                        String varNameExpr = new String(chars, startPos + startMatchLen, pos - startPos - startMatchLen);\n                        if (substitutionInVariablesEnabled)\n                        {\n                            final StrBuilder bufName = new StrBuilder(varNameExpr);\n                            substitute(bufName, 0, bufName.length());\n                            varNameExpr = bufName.toString();\n                        }\n                        pos += endMatchLen;\n                        final int endPos = pos;\n                        String varName = varNameExpr;\n                        String varDefaultValue = null;\n                        if (valueDelimMatcher != null)\n                        {\n                            final char[] varNameExprChars = varNameExpr.toCharArray();\n                            int valueDelimiterMatchLen = 0;\n                            for (int i = 0;\n                            i < varNameExprChars.length;\n                            i++)\n                            {\n                                // if there's any nested variable when nested variable substitution disabled, // then stop resolving name and default value. if (!substitutionInVariablesEnabled && pfxMatcher.isMatch(varNameExprChars, i, i, varNameExprChars.length) != 0)\n                                {\n                                    break;\n                                }\n                                if (valueDelimMatcher.isMatch(varNameExprChars, i) != 0)\n                                {\n                                    valueDelimiterMatchLen = valueDelimMatcher.isMatch(varNameExprChars, i);\n                        