rVariables .remove(priorVariables.size() - 1);\n                        break;\n                    }\n                    nestedVarCount--;\n                    pos += endMatchLen;\n                }\n            }\n        }\n    }\n    if (top)\n    {\n        return altered ? 1 : 0;\n    }\n    return lengthChange;\n}\n```"
