             nestedVarCount++;\n                    pos += endMatchLen;\n                    continue;\n                }\n                endMatchLen = suffixMatcher.isMatch(builder, pos, offset, bufEnd);\n                if (endMatchLen == 0)\n                {\n                    pos++;\n                }\n                else\n                {\n                    // found variable end marker if (nestedVarCount == 0)\n                    {\n                        if (escPos >= 0)\n                        {\n                            // delete escape builder.deleteCharAt(escPos);\n                            escPos = -1;\n                            lengthChange--;\n                            altered = true;\n                            bufEnd--;\n                            pos = startPos + 1;\n                            startPos--;\n                            continue outer;\n                        }\n                        // get var name String varNameExpr = builder.midString(startPos + startMatchLen, pos - startPos - startMatchLen);\n                        if (substitutionInVariablesEnabled)\n                        {\n                            final TextStringBuilder bufName = new TextStringBuilder(varNameExpr);\n                            substitute(bufName, 0, bufName.length());\n                            varNameExpr = bufName.toString();\n                        }\n                        pos += endMatchLen;\n                        final int endPos = pos;\n                        String varName = varNameExpr;\n                        String varDefaultValue = null;\n                        if (valueDelimMatcher != null)\n                        {\n                            final char[] varNameExprChars = varNameExpr.toCharArray();\n                            int valueDelimiterMatchLen = 0;\n                            for (int i = 0;\n                            i < varNameExprChars.length;\n                            i++)\n          